"use client"

import * as React from "react"
import { CircleAlertIcon, MinusIcon, PlusIcon, RotateCcwIcon } from "lucide-react"
import { cn } from "@/lib/utils"
import { onThemeChange, resolveCssColor, toneVar, type ClinicalTone } from "@/lib/clinical-tone"
import {
  AmbientLight,
  Box3,
  Color,
  DirectionalLight,
  HemisphereLight,
  Mesh,
  MeshStandardMaterial,
  PerspectiveCamera,
  Raycaster,
  Scene,
  Spherical,
  Vector2,
  Vector3,
  WebGLRenderer,
  type Group,
  type Intersection,
  type Material,
  type Object3D,
  SRGBColorSpace,
} from "three"
import { GLTFLoader } from "three/addons/loaders/GLTFLoader.js"
import { OrbitControls } from "three/addons/controls/OrbitControls.js"

import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert"
import { Button } from "@/components/ui/button"
import { Progress } from "@/components/ui/progress"
import {
  Select,
  SelectContent,
  SelectGroup,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/components/ui/tooltip"

export type OrganStructure = {
  /** Mesh name, or `userData.structureId`, of the structure in the GLB. */
  id: string
  label: string
  /** Interface grouping, as shown in the explorer's anatomy panel. */
  group: string
  /** Theme token for the structure. Retana UI maps OrganUI colours onto host tokens. */
  tone: ClinicalTone
  /** Lightness nudge, -1..1: positive mixes toward background, negative toward foreground. */
  shade?: number
  description?: string
}

export type OrganView = {
  name: string
  /**
   * Camera direction from the framing centre in model space: +x is the
   * patient's left, +y superior and +z anterior.
   */
  direction: readonly [number, number, number]
  /** Frame only these structures. Defaults to the whole model. */
  structureIds?: readonly string[]
}

export type OrganModel = {
  name: string
  /** GLB URL: a commit-pinned file in the organ's explorer repository, or one served by organui.com. */
  src: string
  /** Expected size in bytes, for progress when the server sends no length. */
  bytes?: number
  structures: readonly OrganStructure[]
  views: readonly OrganView[]
  defaultView: string
  /** Structures the explorer hides on first load. */
  hiddenIds?: readonly string[]
  attribution: {
    credit: string
    license: string
    licenseUrl: string
    source: string
  }
}

export type OrganViewerHandle = {
  setView: (name: string) => void
  zoom: (factor: number) => void
  rotate: (azimuth: number, polar?: number) => void
  reset: () => void
}

export type OrganViewerProps = {
  model: OrganModel
  /** Overrides `model.src`, for example to serve the GLB yourself. */
  src?: string
  selectedId?: string | null
  onSelectionChange?: (id: string) => void
  /** Missing IDs are visible, matching the anatomy tree's contract. */
  visibility?: Readonly<Record<string, boolean>>
  defaultView?: string
  /** Called with the view name, or null once the camera is rotated freely. */
  onViewChange?: (view: string | null) => void
  /** Shows the view menu, zoom and reset buttons. Defaults to true. */
  controls?: boolean
  /** Shows the model credit and licence link. Keep it unless you credit the model elsewhere. */
  attribution?: boolean
  label?: string
  className?: string
  ref?: React.Ref<OrganViewerHandle>
}

/** Rows for the OrganUI anatomy tree: non-selectable groups of coloured leaves. */
export function organAnatomyNodes(model: OrganModel) {
  const groups = [...new Set(model.structures.map(({ group }) => group))]
  return groups.map((group) => ({
    id: `group-${group.toLowerCase().replace(/[^a-z0-9]+/g, "-")}`,
    label: group,
    selectable: false,
    children: model.structures
      .filter((structure) => structure.group === group)
      .map(({ id, label, tone, shade }) => ({ id, label, color: toneVar(tone, shade) })),
  }))
}

/** The explorer's initial visibility, as an anatomy tree visibility map. */
export function organDefaultVisibility(
  model: OrganModel
): Record<string, boolean> {
  return Object.fromEntries((model.hiddenIds ?? []).map((id) => [id, false]))
}

// Shared with every OrganUI explorer so named views fill the stage by the same
// rule whatever the organ's shape.
const FRAME_FILL = 0.8
/** Neutral white light. Lighting is physical, not a theme colour. */
const LIGHT = () => new Color(1, 1, 1)
const NO_EMISSION = new Color(0, 0, 0)

function tokenColor(value: string, scope: Element | null, fallback: number) {
  const rgb = resolveCssColor(value, scope)
  const color = new Color()
  if (rgb) color.setRGB(rgb[0], rgb[1], rgb[2], SRGBColorSpace)
  else color.setScalar(fallback)
  return color
}

function surfacePoints(meshes: Mesh[], stride = 16) {
  const points: Vector3[] = []
  for (const mesh of meshes) {
    mesh.updateWorldMatrix(true, false)
    const position = mesh.geometry.getAttribute("position")
    for (let i = 0; i < position.count; i += stride)
      points.push(
        new Vector3()
          .fromBufferAttribute(position, i)
          .applyMatrix4(mesh.matrixWorld)
      )
  }
  return points
}

// Distance along `direction` at which every sampled point sits inside
// FRAME_FILL of the frustum.
function fitDistance(
  points: Vector3[],
  center: Vector3,
  direction: Vector3,
  fov: number,
  aspect: number
) {
  const forward = direction.clone().normalize()
  const right = new Vector3(0, 1, 0).cross(forward)
  if (right.lengthSq() < 1e-8) right.set(1, 0, 0)
  right.normalize()
  const up = forward.clone().cross(right).normalize()
  const tanV = Math.tan((fov * Math.PI) / 360) * FRAME_FILL
  const tanH = tanV * aspect
  const offset = new Vector3()
  let distance = 0
  for (const point of points) {
    offset.subVectors(point, center)
    distance = Math.max(
      distance,
      offset.dot(forward) +
        Math.max(
          Math.abs(offset.dot(right)) / tanH,
          Math.abs(offset.dot(up)) / tanV
        )
    )
  }
  return distance
}

// Ghosts stay pickable when nothing solid is behind them, but solid anatomy
// seen through a translucent shell wins the click.
function pickVisibleMesh(hits: Intersection<Object3D>[]) {
  const meshes = hits
    .map(({ object }) => object)
    .filter((object): object is Mesh => {
      if (!(object instanceof Mesh)) return false
      for (let parent: Object3D | null = object; parent; parent = parent.parent)
        if (!parent.visible) return false
      return true
    })
  return (
    meshes.find((mesh) => {
      const material = mesh.material as Material
      return !material.transparent || material.opacity >= 1
    }) ?? meshes[0]
  )
}

// A structure may be a mesh, or a node whose meshes are its children.
function structureId(object: Object3D, known: ReadonlySet<string>) {
  for (let node: Object3D | null = object; node; node = node.parent) {
    const id: string = node.userData.structureId || node.name
    if (known.has(id)) return id
  }
}

function dispose(model: Group) {
  model.traverse((object) => {
    if (!(object instanceof Mesh)) return
    object.geometry.dispose()
    const materials = Array.isArray(object.material)
      ? object.material
      : [object.material]
    materials.forEach((material: Material) => material.dispose())
  })
}

async function loadModel(
  src: string,
  expected: number | undefined,
  signal: AbortSignal,
  onProgress: (percent: number) => void
) {
  const response = await fetch(src, { signal })
  if (!response.ok)
    throw new Error(`The model request returned HTTP ${response.status}.`)
  const total = Number(response.headers.get("content-length")) || expected || 0
  const reader = response.body?.getReader()
  let data: ArrayBuffer
  if (reader) {
    const chunks: Uint8Array[] = []
    let received = 0
    for (;;) {
      const { done, value } = await reader.read()
      if (done) break
      chunks.push(value)
      received += value.length
      if (total) onProgress(Math.min(95, Math.round((received / total) * 95)))
    }
    const bytes = new Uint8Array(received)
    let offset = 0
    for (const chunk of chunks) {
      bytes.set(chunk, offset)
      offset += chunk.length
    }
    data = bytes.buffer
  } else data = await response.arrayBuffer()
  if (
    data.byteLength < 12 ||
    new DataView(data).getUint32(0, true) !== 0x46546c67
  )
    throw new Error("The model file is missing or is not a valid GLB.")
  return (await new GLTFLoader().parseAsync(data, "")).scene
}

type Engine = OrganViewerHandle & {
  paint: (
    selectedId: string | null,
    visibility: Readonly<Record<string, boolean>>
  ) => void
}

function ToolbarButton({
  label,
  onClick,
  children,
}: {
  label: string
  onClick: () => void
  children: React.ReactNode
}) {
  return (
    <Tooltip>
      <TooltipTrigger asChild>
        <Button
            variant="ghost"
            size="icon"
            aria-label={label}
            onClick={onClick}
        >
          {children}
        </Button>
      </TooltipTrigger>
      <TooltipContent side="bottom">{label}</TooltipContent>
    </Tooltip>
  )
}

export function OrganViewer({
  model,
  src = model.src,
  selectedId = null,
  onSelectionChange,
  visibility,
  defaultView = model.defaultView,
  onViewChange,
  controls = true,
  attribution = true,
  label = `Interactive ${model.name.toLowerCase()} model`,
  className,
  ref,
}: OrganViewerProps) {
  const host = React.useRef<HTMLDivElement>(null)
  const [attempt, setAttempt] = React.useState(0)
  // Load results are keyed by request so a new src or retry starts clean
  // without resetting state inside the effect.
  const request = `${attempt}:${src}`
  const [result, setResult] = React.useState<{
    request: string
    scene?: Group
    error?: string
  } | null>(null)
  const [loading, setLoading] = React.useState({ request, progress: 0 })
  const scene = result?.request === request ? (result.scene ?? null) : null
  const error = result?.request === request ? (result.error ?? null) : null
  const progress = loading.request === request ? loading.progress : 0
  const [graphicsFailed, setGraphicsFailed] = React.useState(false)
  const [engine, setEngine] = React.useState<Engine | null>(null)
  const [view, setView] = React.useState<string | null>(defaultView)
  const [interacted, setInteracted] = React.useState(false)
  const latest = React.useRef({
    model,
    defaultView,
    onSelectionChange,
    onViewChange,
  })
  React.useLayoutEffect(() => {
    latest.current = { model, defaultView, onSelectionChange, onViewChange }
  })
  const instructions = React.useId()

  const shown = React.useMemo(
    () => visibility ?? organDefaultVisibility(model),
    [visibility, model]
  )
  const viewRef = React.useRef(view)
  const changeView = React.useCallback((next: string | null) => {
    if (viewRef.current === next) return
    viewRef.current = next
    setView(next)
    latest.current.onViewChange?.(next)
  }, [])

  React.useEffect(() => {
    const abort = new AbortController()
    let loaded: Group | null = null
    const timeout = setTimeout(() => abort.abort("timeout"), 60_000)
    loadModel(src, latest.current.model.bytes, abort.signal, (percent) =>
      setLoading({ request, progress: percent })
    )
      .then((group) => {
        loaded = group
        if (abort.signal.aborted) return dispose(group)
        const known = new Set(
          latest.current.model.structures.map(({ id }) => id)
        )
        const found = new Set<string>()
        group.traverse((object) => {
          const id = object instanceof Mesh && structureId(object, known)
          if (id) found.add(id)
        })
        const missing = [...known].filter((id) => !found.has(id))
        if (missing.length)
          throw new Error("The model does not contain the expected structures.")
        setResult({ request, scene: group })
      })
      .catch((reason: unknown) => {
        if (abort.signal.aborted && abort.signal.reason !== "timeout") return
        setResult({
          request,
          error:
            abort.signal.reason === "timeout"
              ? "The download timed out."
              : reason instanceof Error
                ? reason.message
                : "The model could not be decoded.",
        })
      })
      .finally(() => clearTimeout(timeout))
    return () => {
      abort.abort("unmount")
      clearTimeout(timeout)
      if (loaded) dispose(loaded)
    }
  }, [src, request])

  React.useEffect(() => {
    const container = host.current
    if (!scene || !container || graphicsFailed) return
    const structures = new Map(
      latest.current.model.structures.map((structure) => [
        structure.id,
        structure,
      ])
    )
    const meshes = new Map<string, Mesh[]>()
    const known = new Set(structures.keys())
    scene.traverse((object) => {
      const id = object instanceof Mesh && structureId(object, known)
      if (!id) return
      // Materials may be shared in the GLB, but emphasis is per structure.
      const source = object.material as MeshStandardMaterial
      object.material =
        source instanceof MeshStandardMaterial
          ? source.clone()
          : new MeshStandardMaterial()
      meshes.set(id, [...(meshes.get(id) ?? []), object])
    })

    const canvas = document.createElement("canvas")
    canvas.className = "block size-full touch-none outline-none"
    canvas.setAttribute("aria-hidden", "true")
    container.prepend(canvas)
    let renderer: WebGLRenderer
    try {
      renderer = new WebGLRenderer({
        canvas,
        antialias: true,
        alpha: true,
        powerPreference: "low-power",
      })
    } catch {
      canvas.remove()
      // WebGL is an external system; its failure is reported once per attempt.
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setGraphicsFailed(true)
      return
    }
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2))
    const stage = new Scene()
    stage.add(new AmbientLight(LIGHT(), 0.8))
    stage.add(new HemisphereLight(LIGHT(), new Color(0.6, 0.6, 0.6), 1.6))
    const lights: [number[], number, Color][] = [
      [[-4, 6, 6], 2.6, LIGHT()],
      [[5, 1, -4], 1.8, LIGHT()],
      [[-3, -3, 0], 0.45, LIGHT()],
    ]
    for (const [position, intensity, color] of lights) {
      const light = new DirectionalLight(color, intensity)
      light.position.set(position[0]!, position[1]!, position[2]!)
      stage.add(light)
    }
    stage.add(scene)
    const camera = new PerspectiveCamera(34, 1, 0.05, 100)
    const orbit = new OrbitControls(camera, canvas)
    orbit.enablePan = false
    orbit.rotateSpeed = 0.65
    orbit.zoomSpeed = 0.8
    const motion = matchMedia("(prefers-reduced-motion: reduce)")
    const applyMotion = () => (orbit.enableDamping = !motion.matches)
    applyMotion()
    motion.addEventListener("change", applyMotion)

    const allMeshes = [...meshes.values()].flat()
    const points = surfacePoints(allMeshes)
    const center = new Box3().setFromPoints(points).getCenter(new Vector3())
    const radius =
      new Box3().setFromObject(scene).getSize(new Vector3()).length() / 2
    const framing = new Map(
      latest.current.model.views.map((entry) => {
        const subset = entry.structureIds?.flatMap((id) => meshes.get(id) ?? [])
        const framed = subset?.length ? surfacePoints(subset) : points
        const target = subset?.length
          ? new Box3().setFromPoints(framed).getCenter(new Vector3())
          : center
        return [entry.name, { entry, framed, target }]
      })
    )
    // Views of a few structures, such as the head of a whole-body model, may
    // come closer than the whole model allows.
    const closest = Math.min(
      radius,
      ...[...framing.values()].map(
        ({ framed }) =>
          new Box3().setFromPoints(framed).getSize(new Vector3()).length() / 2
      )
    )
    camera.near = closest / 100
    camera.far = radius * 20
    orbit.minDistance = closest * 1.25
    orbit.maxDistance = radius * 6

    let dirty = true
    const render = () => (dirty = true)
    let frame = 0
    const tick = () => {
      if (orbit.update() || dirty) {
        renderer.render(stage, camera)
        dirty = false
      }
      frame = requestAnimationFrame(tick)
    }

    let current: string | null = latest.current.defaultView
    const preset = (name: string) => {
      const target = framing.get(name) ?? framing.values().next().value
      if (!target) return
      orbit.reset()
      const direction = new Vector3(...target.entry.direction).normalize()
      const distance = Math.min(
        orbit.maxDistance,
        Math.max(
          orbit.minDistance,
          fitDistance(
            target.framed,
            target.target,
            direction,
            camera.fov,
            camera.aspect
          )
        )
      )
      orbit.target.copy(target.target)
      camera.position
        .copy(direction)
        .multiplyScalar(distance)
        .add(target.target)
      camera.lookAt(target.target)
      orbit.update()
      current = target.entry.name
      changeView(current)
      render()
    }

    const resize = () => {
      const width = container.clientWidth
      const height = container.clientHeight
      if (!width || !height) return
      const aspect = width / height
      const changed = Math.abs(aspect - camera.aspect) > 1e-6
      renderer.setSize(width, height, false)
      camera.aspect = aspect
      camera.updateProjectionMatrix()
      // A named view is refitted; a free camera keeps its target and distance.
      if (changed && current) preset(current)
      render()
    }
    const observer = new ResizeObserver(resize)
    observer.observe(container)
    camera.aspect = container.clientWidth / Math.max(1, container.clientHeight)
    renderer.setSize(container.clientWidth, container.clientHeight, false)
    camera.updateProjectionMatrix()
    preset(latest.current.defaultView)

    let interacting = false
    const lastRotation = camera.quaternion.clone()
    const onStart = () => (interacting = true)
    const onEnd = () => (interacting = false)
    const onChange = () => {
      if (interacting) {
        setInteracted(true)
        if (1 - Math.abs(lastRotation.dot(camera.quaternion)) > 1e-10) {
          current = null
          changeView(null)
        }
      }
      lastRotation.copy(camera.quaternion)
      render()
    }
    orbit.addEventListener("start", onStart)
    orbit.addEventListener("end", onEnd)
    orbit.addEventListener("change", onChange)

    const raycaster = new Raycaster()
    const down = new Vector2()
    const onPointerDown = (event: PointerEvent) =>
      down.set(event.clientX, event.clientY)
    const onPointerUp = (event: PointerEvent) => {
      if (down.distanceTo(new Vector2(event.clientX, event.clientY)) > 4) return
      const bounds = canvas.getBoundingClientRect()
      raycaster.setFromCamera(
        new Vector2(
          ((event.clientX - bounds.left) / bounds.width) * 2 - 1,
          -((event.clientY - bounds.top) / bounds.height) * 2 + 1
        ),
        camera
      )
      const mesh = pickVisibleMesh(raycaster.intersectObjects(allMeshes, false))
      const id = mesh && structureId(mesh, known)
      if (id) latest.current.onSelectionChange?.(id)
    }
    canvas.addEventListener("pointerdown", onPointerDown)
    canvas.addEventListener("pointerup", onPointerUp)
    const onContextLost = (event: Event) => {
      event.preventDefault()
      setGraphicsFailed(true)
    }
    canvas.addEventListener("webglcontextlost", onContextLost)

    let ghosts = new Map<string, Color>()
    let tints = new Map<string, Color>()
    let stageTone = tokenColor("var(--muted)", canvas, 0.9)
    let lastPaint: [string | null, Readonly<Record<string, boolean>>] | null = null
    const stopTheme = onThemeChange(() => {
      ghosts = new Map()
      tints = new Map()
      stageTone = tokenColor("var(--muted)", canvas, 0.9)
      if (lastPaint) engineValue.paint(lastPaint[0], lastPaint[1])
    })
    const tintOf = (id: string) => {
      const structure = structures.get(id)!
      const key = toneVar(structure.tone, structure.shade)
      let tint = tints.get(key)
      if (!tint) {
        tint = tokenColor(key, canvas, 0.6)
        tints.set(key, tint)
      }
      return { key, tint }
    }
    const engineValue: Engine = {
      paint(selected, shown) {
        lastPaint = [selected, shown]
        for (const [id, list] of meshes) {
          const { key: color, tint } = tintOf(id)
          const state = !selected
            ? "normal"
            : id === selected
              ? "selected"
              : "ghosted"
          let ghost = ghosts.get(color)
          if (!ghost) {
            ghost = tint.clone().lerp(stageTone, 0.5)
            ghosts.set(color, ghost)
          }
          for (const mesh of list) {
            const material = mesh.material as MeshStandardMaterial
            mesh.visible = shown[id] !== false
            if (state === "ghosted") material.color.copy(ghost)
            else material.color.copy(tint)
            material.emissive.copy(state === "selected" ? tint : NO_EMISSION)
            material.emissiveIntensity = state === "selected" ? 0.35 : 0
            material.transparent = state === "ghosted"
            material.opacity = state === "ghosted" ? 0.22 : 1
            material.depthWrite = state !== "ghosted"
            material.roughness = 0.58
            // glTF defaults to fully metallic when a file omits the factor.
            material.metalness = 0
            material.needsUpdate = true
          }
        }
        render()
      },
      setView: preset,
      reset: () => preset(latest.current.defaultView),
      zoom(factor) {
        const offset = camera.position.clone().sub(orbit.target)
        offset.setLength(
          Math.min(
            orbit.maxDistance,
            Math.max(orbit.minDistance, offset.length() * factor)
          )
        )
        camera.position.copy(orbit.target).add(offset)
        orbit.update()
        setInteracted(true)
        render()
      },
      rotate(azimuth, polar = 0) {
        const spherical = new Spherical().setFromVector3(
          camera.position.clone().sub(orbit.target)
        )
        spherical.theta += azimuth
        spherical.phi += polar
        spherical.makeSafe()
        camera.position
          .copy(orbit.target)
          .add(new Vector3().setFromSpherical(spherical))
        orbit.update()
        current = null
        changeView(null)
        setInteracted(true)
        render()
      },
    }
    setEngine(engineValue)
    frame = requestAnimationFrame(tick)

    return () => {
      cancelAnimationFrame(frame)
      stopTheme()
      setEngine(null)
      observer.disconnect()
      motion.removeEventListener("change", applyMotion)
      canvas.removeEventListener("pointerdown", onPointerDown)
      canvas.removeEventListener("pointerup", onPointerUp)
      canvas.removeEventListener("webglcontextlost", onContextLost)
      orbit.dispose()
      stage.remove(scene)
      renderer.dispose()
      canvas.remove()
    }
  }, [scene, graphicsFailed, changeView])

  React.useEffect(() => {
    engine?.paint(selectedId, shown)
  }, [engine, selectedId, shown])

  React.useImperativeHandle(
    ref,
    () => ({
      setView: (name) => engine?.setView(name),
      zoom: (factor) => engine?.zoom(factor),
      rotate: (azimuth, polar) => engine?.rotate(azimuth, polar),
      reset: () => engine?.reset(),
    }),
    [engine]
  )

  const retry = () => {
    setGraphicsFailed(false)
    setAttempt((n) => n + 1)
  }
  const message = error
    ? {
        title: `The ${model.name.toLowerCase()} model couldn’t load`,
        text: `${error} Check your connection and try again.`,
      }
    : graphicsFailed
      ? {
          title: "3D view unavailable",
          text: "WebGL could not start or its connection was interrupted. Try again, or use a browser with hardware acceleration enabled.",
        }
      : null

  return (
    <div
      ref={host}
      role="region"
      aria-label={label}
      aria-describedby={instructions}
      tabIndex={0}
      className={cn(
        "relative h-96 w-full overflow-hidden rounded-xl border bg-muted/30 text-sm text-foreground focus-visible:outline-2 focus-visible:outline-ring",
        className
      )}
      onKeyDown={(event) => {
        if (event.target !== event.currentTarget || !engine) return
        const actions: Record<string, () => void> = {
          ArrowLeft: () => engine.rotate(-0.2),
          ArrowRight: () => engine.rotate(0.2),
          ArrowUp: () => engine.rotate(0, -0.2),
          ArrowDown: () => engine.rotate(0, 0.2),
          "+": () => engine.zoom(0.85),
          "=": () => engine.zoom(0.85),
          "-": () => engine.zoom(1.18),
        }
        const action = actions[event.key]
        if (!action) return
        event.preventDefault()
        action()
      }}
    >
      <p id={instructions} className="sr-only">
        Drag or use the arrow keys to rotate, and scroll, pinch or press plus
        and minus to zoom. Click a structure to select it.
      </p>
      {message ? (
        <div className="absolute inset-0 flex items-center justify-center p-6">
          <Alert className="max-w-sm">
            <CircleAlertIcon
              aria-hidden="true"
            />
            <AlertTitle>{message.title}</AlertTitle>
            <AlertDescription>
              <p>{message.text}</p>
              <Button
                variant="outline"
                size="sm"
                onClick={retry}
                className="mt-3 text-foreground"
              >
                Try again
              </Button>
            </AlertDescription>
          </Alert>
        </div>
      ) : !scene ? (
        <div
          role="status"
          className="absolute inset-0 flex flex-col items-center justify-center gap-3 p-6"
        >
          <Progress
            value={progress}
            aria-label={`Loading ${model.name.toLowerCase()} model`}
            className="w-40"
          />
          <p className="text-muted-foreground">{progress}% · Loading anatomy</p>
        </div>
      ) : null}
      {engine && controls && (
        <TooltipProvider>
          <div
            role="toolbar"
            aria-label="View controls"
            className="absolute top-2 right-2 flex items-center gap-0.5 rounded-lg border bg-background/90 p-1 shadow-sm backdrop-blur"
          >
            <Select
              value={view ?? ""}
              onValueChange={(next) => {
                if (next) engine.setView(next)
              }}
            >
              <SelectTrigger aria-label="View" className="border-transparent">
                <SelectValue placeholder="Custom view" />
              </SelectTrigger>
              <SelectContent>
                <SelectGroup>
                  {model.views.map(({ name }) => (
                    <SelectItem key={name} value={name}>
                      {name}
                    </SelectItem>
                  ))}
                </SelectGroup>
              </SelectContent>
            </Select>
            <ToolbarButton label="Zoom in" onClick={() => engine.zoom(0.85)}>
              <PlusIcon
                aria-hidden="true"
              />
            </ToolbarButton>
            <ToolbarButton label="Zoom out" onClick={() => engine.zoom(1.18)}>
              <MinusIcon
                aria-hidden="true"
              />
            </ToolbarButton>
            <ToolbarButton label="Reset view" onClick={() => engine.reset()}>
              <RotateCcwIcon
                aria-hidden="true"
              />
            </ToolbarButton>
          </div>
        </TooltipProvider>
      )}
      {engine && !interacted && (
        <p
          aria-hidden="true"
          className="pointer-events-none absolute inset-x-0 bottom-8 text-center text-xs text-muted-foreground"
        >
          Drag to rotate · Scroll or pinch to zoom
        </p>
      )}
      {attribution && (
        <p className="absolute right-2 bottom-1.5 left-2 flex justify-end gap-1 text-[11px] text-muted-foreground">
          <a
            href={model.attribution.source}
            className="min-w-0 truncate underline-offset-2 hover:underline"
          >
            {model.attribution.credit}
          </a>
          <span aria-hidden="true">·</span>
          <a
            href={model.attribution.licenseUrl}
            className="shrink-0 underline-offset-2 hover:underline"
          >
            {model.attribution.license}
          </a>
        </p>
      )}
    </div>
  )
}

/**
 * Theme tokens for clinical and anatomy pieces.
 *
 * OrganUI ships fixed anatomical colours. Retana UI items inherit the host
 * theme instead, so every structure, trace and fill names a token and an
 * optional lightness shade. SVG and CSS use the token directly; WebGL reads
 * the resolved token once per theme change.
 */
export type ClinicalTone =
  | "chart-1"
  | "chart-2"
  | "chart-3"
  | "chart-4"
  | "chart-5"
  | "primary"
  | "destructive"
  | "muted-foreground"
  | "foreground"

export const CLINICAL_TONES: readonly ClinicalTone[] = [
  "chart-1",
  "chart-2",
  "chart-3",
  "chart-4",
  "chart-5",
]

/** CSS value for a tone. shade -1..1 mixes toward background (+) or foreground (-). */
export function toneVar(tone: ClinicalTone, shade = 0) {
  if (!shade) return `var(--${tone})`
  const pct = Math.round(Math.min(Math.abs(shade), 1) * 100)
  return shade > 0
    ? `color-mix(in oklch, var(--${tone}), var(--background) ${pct}%)`
    : `color-mix(in oklch, var(--${tone}), var(--foreground) ${pct}%)`
}

/** A tone picked by position, for series without a fixed meaning. */
export function toneAt(index: number): ClinicalTone {
  return CLINICAL_TONES[((index % CLINICAL_TONES.length) + CLINICAL_TONES.length) % CLINICAL_TONES.length]!
}

export type Rgb = readonly [number, number, number]

const cache = new Map<string, Rgb>()
let probe: CanvasRenderingContext2D | null | undefined

/**
 * Resolve any CSS colour expression (tokens, color-mix) to sRGB 0..1 by
 * painting one pixel. Returns null outside the browser.
 */
export function resolveCssColor(value: string, scope?: Element | null): Rgb | null {
  if (typeof document === "undefined") return null
  const key = value
  const hit = cache.get(key)
  if (hit) return hit
  const host = document.createElement("span")
  host.style.color = value
  host.style.display = "none"
  ;(scope ?? document.body).appendChild(host)
  const computed = getComputedStyle(host).color
  host.remove()
  if (probe === undefined) {
    const canvas = document.createElement("canvas")
    canvas.width = canvas.height = 1
    probe = canvas.getContext("2d", { willReadFrequently: true })
  }
  if (!probe || !computed) return null
  probe.clearRect(0, 0, 1, 1)
  probe.fillStyle = computed
  probe.fillRect(0, 0, 1, 1)
  const [r, g, b] = probe.getImageData(0, 0, 1, 1).data
  const rgb: Rgb = [r! / 255, g! / 255, b! / 255]
  cache.set(key, rgb)
  return rgb
}

/** Drop resolved colours, for example after the host switches theme. */
export function clearToneCache() {
  cache.clear()
}

/** Call back when the document theme class or style changes. */
export function onThemeChange(callback: () => void) {
  if (typeof MutationObserver === "undefined" || typeof document === "undefined") return () => {}
  const observer = new MutationObserver(() => {
    clearToneCache()
    callback()
  })
  observer.observe(document.documentElement, { attributes: true, attributeFilter: ["class", "style", "data-theme"] })
  return () => observer.disconnect()
}
